from collections import deque


class BoundedQueue:
    """FIFO queue of ints with a fixed capacity. Puts never block."""

    def __init__(self, capacity: int) -> None:
        """Create an empty queue that holds at most `capacity` items."""
        self._capacity: int = capacity
        self._items: deque[int] = deque()

    def try_put(self, item: int) -> bool:
        """Append `item` if there is room. Return False without blocking when full."""
        if len(self._items) >= self._capacity:
            return False
        self._items.append(item)
        return True

    def __len__(self) -> int:
        """Return the number of items currently in the queue."""
        return len(self._items)


def accepted(cap: int, xs: list[int]) -> int:
    """Put each element of xs into a queue of capacity cap without blocking.

    Count the puts accepted before the queue first reports full, then stop.
    Return that count.
    """
    q = BoundedQueue(cap)
    count = 0
    for x in xs:
        if not q.try_put(x):
            break
        count += 1
    return count


def test_accepted_stops_at_capacity() -> None:
    assert accepted(2, [1, 2, 3, 4]) == 2


def test_accepted_all_fit() -> None:
    assert accepted(5, [1, 2, 3]) == 3


def test_accepted_zero_capacity() -> None:
    assert accepted(0, [1, 2]) == 0


def test_accepted_empty_input() -> None:
    assert accepted(3, []) == 0


def test_try_put_rejects_when_full() -> None:
    q = BoundedQueue(1)
    assert q.try_put(1) is True
    assert q.try_put(2) is False
    assert len(q) == 1
